82	CREATE OR REPLACE FUNCTION set_updated_at()
83	RETURNS TRIGGER
84	LANGUAGE plpgsql
85	AS $$
86	BEGIN
87	  NEW.updated_at = now();
88	  RETURN NEW;
89	END;
90	$$;
91	
92	COMMENT ON FUNCTION set_updated_at() IS
93	  'Helper trigger: sets updated_at = now() on every UPDATE. '
94	  'Idempotent CREATE OR REPLACE — safe to re-run.';
